-- OPS-FAILOVER-2 (2026-11-05, charter pillars autonomy and security; roadmap row RM-S1-REDUNDANCY-1 id 5; follow-up of migrations/2026-11-04-c5-resilience-ops-failover.sql, which said the SPOF row waits for the first runner reading).
-- READ LIVE: metric ops_gateway_hosts_ok = 1, state MEASURED, refresh_class runner, last_refreshed 2026-11-05T00:35:02Z, written by scripts/bp26_opsfailover.py in the 00:38Z consumer sweep (cloud_ops_events bp26-producers lists ops_failover among the collectors it ran).
-- WHAT THIS DOES: registers the gateway HOSTNAME as a single point of failure with its alternate, so the doctrine accounting names it, and gives the chaos drill (qnfo-fleet-control chaosDrill, every 6 h) a probe that reads the runner measurement. The registry row starts with alternate_tested_at NULL on purpose:
-- the drill stamps it only when the probe passes (see the evidence of the other spof_registry rows), so spofs_on_critical_path reads one higher until the next drill, then falls back; the probe row is enabled now because the measurement it reads exists. Also files the Windows-only failure of scripts/direct_content_deploy.py --selftest found while
-- verifying T9, so it is not left as prose. Row 5 stays partial: the read-only degraded mode (ROADMAP-1 OPS-DEGRADED-1) is not built.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM spof_alternate_probes WHERE component = 'qnfo-ops gateway hostname (ops.qnfo.org)'; DELETE FROM spof_registry WHERE component = 'qnfo-ops gateway hostname (ops.qnfo.org)'; DELETE FROM agent_issues WHERE source = 'session:c5-resilience' AND title LIKE 'ROADMAP-1: QNFO.INFRA DIRECT-DEPLOY-WINDOWS-1:%'; UPDATE roadmap_implementation SET evidence = substr(evidence, 1, instr(evidence, ' || C5-RESILIENCE-5B ') - 1) WHERE id = 5 AND instr(evidence, ' || C5-RESILIENCE-5B ') > 0;
-- BACKUP: agent_issues

INSERT OR IGNORE INTO spof_registry (component, critical_path, alternate_path, alternate_tested_at, evidence, issue_id, reviewed_at)
VALUES ('qnfo-ops gateway hostname (ops.qnfo.org)',
  'every session, runner and external client call to the ops tool surface, /ops/deploy and the OpenAI-compatible ops endpoint names the hostname ops.qnfo.org, a Cloudflare custom domain on the qnfo.org zone; callers inside the account use the service binding, which needs neither DNS nor the zone',
  'the same worker answers on https://qnfo-ops.q08.workers.dev (workers_dev = true in qnfo-ops/wrangler.toml, added 2026-09-30). scripts/bp26_opsfailover.py reads /health and /v1/models on both hostnames hourly from the GitHub runner (a Worker cannot fetch its own account workers.dev hosts, error 1042) and writes metric ops_gateway_hosts_ok. This is a second HOSTNAME for the one worker: it covers a zone, DNS, WAF or Access fault on ops.qnfo.org (the rollouts in docs/CF-ACCESS-ROLLOUT-1277.md and RM-WAF-RATE-LIMIT-1 would be that fault), not a broken deploy (canary revert and scripts/direct_content_deploy.py cover that) and not a worker or D1 outage (ROADMAP-1 OPS-DEGRADED-1 is the open slice). Clients still name ops.qnfo.org: switching a client to the alternate is a manual step.',
  NULL,
  'RM-S1-REDUNDANCY-1 (roadmap row 5), migrations/2026-11-04-c5-resilience-ops-failover.sql. Read 2026-11-05: both hostnames served qnfo-ops 2.63.0-tool-arg-alias (/health 200 and /v1/models 200 on each, 190 ms and 140 ms); ops_gateway_hosts_ok = 1 written by the runner at 00:35:02Z. alternate_tested_at is stamped only by a passing chaos drill on the spof_alternate_probes row of this component.',
  NULL, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));

INSERT OR IGNORE INTO spof_alternate_probes (component, probe_sql, exercise, window_note)
VALUES ('qnfo-ops gateway hostname (ops.qnfo.org)',
  'SELECT ''ok'' AS expected, CASE WHEN (SELECT last_value FROM metric_registry WHERE metric = ''ops_gateway_hosts_ok'') IS NULL THEN ''ops_gateway_hosts_ok has no value: the runner collector has not measured the alternate hostname'' WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''ops_gateway_hosts_ok'') AS REAL) < 1 THEN ''ops_gateway_hosts_ok is below 1: a gateway hostname does not serve qnfo-ops'' WHEN (SELECT last_refreshed FROM metric_registry WHERE metric = ''ops_gateway_hosts_ok'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 hours'') THEN ''ops_gateway_hosts_ok was not refreshed in 3 hours: the runner collector did not run'' ELSE ''ok'' END AS observed',
  NULL, '3 h: scripts/bp26_opsfailover.py writes ops_gateway_hosts_ok from the GitHub runner about hourly; the probe passes only while it reads 1 and was refreshed within 3 hours (a sweep that spends its budget before the collector can delay it by one cycle)');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.INFRA DIRECT-DEPLOY-WINDOWS-1: scripts/direct_content_deploy.py --selftest fails on Windows (path separator in collect_modules)',
 'QNFO.INFRA; charter pillar core; roadmap row RM-TP-9-DEPLOY-NO-LOCKOUT (lever 3 second deploy path). Found 2026-11-05 while verifying T9 on a Windows checkout: python scripts/direct_content_deploy.py --selftest and scripts/direct-content-deploy-ledger.test.mjs (which runs it) fail with OSError: m\\oauth-broker.mjs. collect_modules calls read(target) with the os.path.normpath result, which has backslashes on Windows, while the selftest fake read is keyed with forward slashes; on Linux, where canonical-deploy.yml runs it, nothing differs, and deploys are green. Work: call read(target.replace("\\", "/")) (open() accepts forward slashes on Windows) or key the fake by os.path.normpath, and add the Windows-shaped case to the selftest so the path cannot regress; no behaviour change on Linux. This script is the second deploy path of the deployer, so the change is small, carries a work claim and is verified with the existing selftest plus the new case. Prediction: the selftest and scripts/direct-content-deploy-ledger.test.mjs pass on Windows and Linux. Closing marker: the change carries the text DIRECT-DEPLOY-WINDOWS-1.' || char(10) ||
 'code-task: repo=qnfo-workers path=scripts/direct_content_deploy.py' || char(10) ||
 'code-anchor: def collect_modules(path, src, read=None):' || char(10) ||
 'code-probe: {"paths":["scripts/direct_content_deploy.py"],"contains":"DIRECT-DEPLOY-WINDOWS-1"}',
 'session:c5-resilience', 'code', 'low', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE instr(title, 'ROADMAP-1: QNFO.INFRA DIRECT-DEPLOY-WINDOWS-1:') = 1 AND status = 'open');

UPDATE roadmap_implementation
SET evidence = evidence || ' || C5-RESILIENCE-5B 2026-11-05: first half VERIFIED LIVE. Read from qnfo-audit: metric ops_gateway_hosts_ok = 1, MEASURED by the runner at 2026-11-05T00:35:02Z (scripts/bp26_opsfailover.py, migration applied 00:24:06Z); both hostnames serve qnfo-ops. This migration registers the gateway hostname as a SPOF with that alternate and an enabled chaos-drill probe (alternate_tested_at is stamped by the next drill). The row stays partial: the read-only degraded mode of qnfo-ops itself (OPS-DEGRADED-1) is not built.'
WHERE id = 5 AND item = 'RM-S1-REDUNDANCY-1' AND instr(evidence, 'C5-RESILIENCE-5B') = 0;
